import json
from langchain_text_splitters import RecursiveCharacterTextSplitter

def clean_and_chunk_merchant_doc(raw_text, category_label, store_id):
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=300,
        chunk_overlap=50,
        separators=['\n\n', '\n', '。', '！']
    )
    docs = splitter.split_text(raw_text)
    chunks = []
    for idx, text in enumerate(docs):
        chunks.append({
            'chunk_id': f'{store_id}_{category_label}_{idx}',
            'content': text,
            'metadata': {
                'store_id': store_id,
                'category': category_label
            }
        })
    return chunks
